"use strict";
const $=id=>document.getElementById(id),t=OrionI18n.t;
const journeys=[[3,6,9],[4,8,12],[2,4,6],[5,10,3],[6,12,6],[7,2,12]];
let variant=OrionProgress.variant('springs'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget,stage=0,length=0,solved=false,hintDepth=0,hintOpen=false,state='ready',saveFailed=false;
function challenge(v=variant,s=stage){return journeys[v][s];}
function stiffness(){return stage+1;}
function effort(n){return n/stiffness();}
function setLength(n){if(solved||!Number.isInteger(n)||n<0||n>12)return;length=n;state='ready';render();}
function resetTrial(){length=0;solved=false;hintDepth=0;hintOpen=false;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('springs')){variant=v;stage=0;resetTrial();}
function check(){if(solved)return;if(length!==challenge())state='wrong';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('elastic');}render();if(solved&&stage<2)$('next').focus();}
function drawing(){const end=100+15*effort(length),target=100+15*effort(challenge());let path='M40 110L50 110';for(let i=0;i<16;i++)path+='L'+(50+(end-60)*i/15)+' '+(i%2?125:95);path+='L'+end+' 110';return `<svg viewBox="0 0 350 250" role="img" aria-label="${t('Spring extension '+effort(length).toFixed(1)+' centimetres','彈簧伸長 '+effort(length).toFixed(1)+' 厘米')}"><rect x="25" y="70" width="15" height="80" fill="#7e9299"/><path d="M100 65V165" stroke="#c3d6d4" stroke-dasharray="3 4"/><path d="M${target} 55V170" stroke="#a2edb4" stroke-width="3" stroke-dasharray="6 4"/><path d="${path}" fill="none" stroke="#edca80" stroke-width="5" stroke-linejoin="round"/><circle cx="${end}" cy="110" r="7" fill="#ffe3a3"/><path d="M${end+10} 110h30l-7 -6m7 6l-7 6" fill="none" stroke="#ffe3a3" stroke-width="3"/><g fill="#e8e6cc" font-size="12" text-anchor="middle">${Array.from({length:13},(_,i)=>`<path d="M${100+i*15} 180v8" stroke="#a6c0c1"/><text x="${100+i*15}" y="207">${i}</text>`).join('')}<text x="190" y="232">${t('Extension · cm','伸長量 · 厘米')}</text><text x="175" y="30">${t('Green dashed line: target','綠色虛線：目標')}</text></g></svg>`;}
function hints(){const q=challenge();return[t('Start at zero force, then gently increase the pull. Watch the spring tip.','先把拉力調至零，再慢慢增加。觀察彈簧末端。'),t('For this spring, doubling the force doubles the extension. The zero mark is its unstretched tip.','這條彈簧的拉力加倍，伸長量也加倍。零刻度是未拉長時的末端。'),t('Try '+q+' N: '+q+' ÷ '+stiffness()+' = '+effort(q)+' cm.','試試 '+q+' N：'+q+' ÷ '+stiffness()+' = '+effort(q)+' 厘米。')];}
function render(){const q=challenge(),complete=solved&&stage===2,p=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Springkeeper’s Gate · Orion','彈簧守護者之門 · Orion');$('stageTitle').textContent=t(`Spring ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 條彈簧 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Spring seals · ${p} / 3`,`彈簧封印 · ${p} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<p?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);$('diagram').innerHTML=drawing();$('length').value=length;$('length').disabled=solved;$('lengthValue').textContent=length+' N';$('length').setAttribute('aria-valuetext',t(`${length} newtons`,`${length} 牛頓`));
$('goal').textContent=t('Stretch this spring by exactly '+effort(q)+' cm to align the gate pin.','把這條彈簧拉長 '+effort(q)+' 厘米，對準門閂。');$('reading').textContent=t('Extension: '+effort(length).toFixed(1)+' cm','伸長量：'+effort(length).toFixed(1)+' 厘米');$('reference').textContent=t('Spring '+(stage+1)+': '+stiffness()+' N of force for each cm of extension.','第 '+(stage+1)+' 條彈簧：每伸長 1 厘米需要 '+stiffness()+' N 拉力。');const messages={ready:['Adjust the pulling force and watch the tip move.','調整拉力，觀察末端移動。'],wrong:[length<q?'Not far enough. Try more force.':'Past the target. Try less force.',length<q?'還未到達目標。試試增加拉力。':'超過目標了。試試減少拉力。'],success:['The pin lines up! Another gate seal opens.','門閂對準了！又一道封印打開。']};$('feedback').textContent=t(...messages[state]);$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintOpen));$('hints').hidden=!hintOpen;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('')+`<li class="close-clues"><button data-close>${t('Close clues','關閉提示')}</button></li>`;
$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('elastic')?t('Elastic Sigil saved in your collection.','彈力符印已存入收藏。'):'';}
$('length').oninput=e=>setLength(Number(e.target.value));
$('hints').onclick=e=>{if(e.target.closest('button[data-close]')){hintOpen=false;render();$('hint').focus();}};window.addEventListener('keydown',e=>{if(e.key==='Escape'&&hintOpen){hintOpen=false;render();$('hint').focus();}});$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);hintOpen=true;render();};
$('replay').onclick=()=>{const v=OrionProgress.nextVariant('springs',variant);observedVariant=OrionProgress.variant('springs');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('elastic');render();};function syncProgress(){const v=OrionProgress.variant('springs'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('elastic')&&!saveFailed)resetMission();else render();}window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
